import gzip
import xml.etree.ElementTree as ET

statement_checks = [
    '1150', '5001', '5000', '5002', '5003', '3001', '3003', '3004', '5007',
    '5011', '5010', '5008', '5009', '5013', '5014', '5015', '5017', '5016',
    '5012', '5018', '5019', '5020', '5021', '5025', '5026', '5027', '5022'
]

with gzip.open('/home/ga/Documents/HECTOR 2024 LLC.kmy', 'rb') as f:
    tree = ET.parse(f)
root = tree.getroot()
accounts = {acc.attrib['id']: acc.attrib['name'] for acc in root.find('ACCOUNTS')}
payees = {p.attrib['id']: p.attrib['name'] for p in root.find('PAYEES')}
chase_id = [k for k, v in accounts.items() if 'Chase' in str(v)][0]

unmatched = []
matched = []
for tx in root.find('TRANSACTIONS'):
    splits = tx.find('SPLITS')
    for s in splits:
        if s.attrib.get('account') == chase_id:
            num = s.attrib.get('number', '')
            val = float(s.attrib.get('value').split('/')[0]) / 100.0
            payee = payees.get(s.attrib.get('payee'), '')
            memo = s.attrib.get('memo', '')
            date = tx.attrib.get('postdate')
            if date == '2022-12-29': # opening balance
                continue

            is_match = False
            if num in statement_checks:
                is_match = True
            elif 'Office Supply Store' in payee and abs(val + 97.63) < 0.01:
                is_match = True
            elif 'Aria Hotel' in payee and abs(val + 1000.0) < 0.01:
                is_match = True
            elif 'Verizon' in payee and abs(val + 287.40) < 0.01:
                is_match = True
            elif ('Deposit' in payee or 'Deposit' in memo) and (abs(val - 31349.0) < 0.01 or abs(val - 3064.0) < 0.01):
                is_match = True

            if is_match:
                matched.append((date, num, payee, val, tx.attrib['id']))
            else:
                unmatched.append((date, num, payee, val, tx.attrib['id']))

print('MATCHED (to be cleared):', len(matched))
for m in matched:
    print(' ', m)
print('UNMATCHED (to leave UNCLEARED):', len(unmatched))
for u in unmatched:
    print(' ', u)
"

